package com.primehr.migration;
import org.flywaydb.core.Flyway;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.Test;import java.sql.DriverManager;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class PrimeHrV41ToV42UpgradeTest {@Test void populatedCompletionSurvivesEvaluationMigration()throws Exception{String db="primehr_v42_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String>p=Map.of("primehrSchema","PUBLIC");Flyway initial=flyway(url,p,"41");initial.migrate();try{try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.ld_completion_case")){r.next();assertThat(r.getLong(1)).isZero();}Flyway upgraded=flyway(url,p,"42");upgraded.migrate();assertThat(upgraded.info().current().getVersion().getVersion()).isEqualTo("42");try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.ld_evaluation_task")){r.next();assertThat(r.getLong(1)).isZero();}}finally{initial.clean();}}private Flyway flyway(String url,Map<String,String>p,String target){return Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(p).target(MigrationVersion.fromVersion(target)).cleanDisabled(false).load();}}
